#include "launcher/gateway_autostart.h"
gateway_autostart_result_t gateway_autostart_check(const gateway_autostart_ops_t*o,void*c){unsigned long pid;if(!o||!o->exists||!o->writable||!o->executable||!o->pid_read||!o->pid_matches)return GATEWAY_AUTOSTART_STORAGE_UNAVAILABLE;if(!o->exists(c,GATEWAY_INSTALL_ROOT))return GATEWAY_AUTOSTART_STORAGE_UNAVAILABLE;if(o->exists(c,GATEWAY_DISABLE_PATH))return GATEWAY_AUTOSTART_DISABLED;if(!o->writable(c,GATEWAY_INSTALL_ROOT))return GATEWAY_AUTOSTART_STORAGE_READ_ONLY;if(!o->exists(c,GATEWAY_BINARY_PATH))return GATEWAY_AUTOSTART_BINARY_MISSING;if(!o->executable(c,GATEWAY_BINARY_PATH))return GATEWAY_AUTOSTART_BINARY_NOT_EXECUTABLE;if(o->pid_read(c,GATEWAY_PID_PATH,&pid)==0)return o->pid_matches(c,pid,GATEWAY_BINARY_PATH)?GATEWAY_AUTOSTART_ALREADY_RUNNING:GATEWAY_AUTOSTART_STALE_PID;return GATEWAY_AUTOSTART_START;}
